<script>
(() => { const input=document.querySelector('#country'), results=document.querySelector('#country-results'); if(input&&results){const options=[...results.querySelectorAll('[data-country]')];const render=()=>{const term=input.value.trim().toLowerCase();let count=0;options.forEach(o=>{const match=o.dataset.country.toLowerCase().includes(term);o.hidden=!match;if(match)count++;});results.hidden=count===0;input.setAttribute('aria-expanded',String(count>0));};input.addEventListener('input',render);input.addEventListener('focus',render);results.addEventListener('mousedown',e=>{const o=e.target.closest('[data-country]');if(!o)return;e.preventDefault();input.value=o.dataset.country;results.hidden=true;input.setAttribute('aria-expanded','false');input.focus();});document.addEventListener('click',e=>{if(!e.target.closest('.country-picker'))results.hidden=true;});} const radios=[...document.querySelectorAll('input[name="business_type"]')], desc=document.querySelector('#business-description'); if(radios.length&&desc){const update=()=>{const selected=radios.find(r=>r.checked);desc.textContent=selected?selected.dataset.description:'';desc.hidden=!selected;};radios.forEach(r=>r.addEventListener('change',update));update();} })();
</script><script>
(() => {
  const input = document.getElementById('card-number');
  const tip = document.getElementById('card-tip');
  if (!input || !tip) return;
  const update = () => { tip.hidden = !(document.activeElement === input || input.value.trim() !== ''); };
  input.addEventListener('focus', update);
  input.addEventListener('input', update);
  input.addEventListener('blur', update);
  update();
})();
</script><script>
(() => {
