  const nameStatus = document.getElementById('store-name-status');
  const upcTip = document.getElementById('upc-tip');
  if (!nameInput || !nameTip || !nameStatus || !upcTip) return;
  const updateName = () => {
    const length = nameInput.value.trim().length;
    nameTip.hidden = !(document.activeElement === nameInput || length > 0);
    nameStatus.textContent = length === 0 ? '' : length < 3 ? 'Enter at least 3 characters' : 'Name format looks good';
    nameStatus.className = length > 0 && length < 3 ? 'status-invalid' : 'status-valid';
  };
  nameInput.addEventListener('focus', updateName);
  nameInput.addEventListener('input', updateName);
  nameInput.addEventListener('blur', updateName);
  document.querySelectorAll('input[name="upcs"]').forEach((radio) => {
    radio.addEventListener('change', () => { upcTip.hidden = false; });
  });
  updateName();
})();
</script><div id="upload-modal" class="upload-modal" hidden><div class="upload-dialog" role="dialog" aria-modal="true" aria-labelledby="upload-title"><button class="upload-close" type="button" aria-label="Close">×</button><h2 id="upload-title">Uploading Instructions</h2><ul><li>Details in the submitted document should match the details you entered.</li><li>The document image must be high quality, colored, unobstructed, and legible.</li><li>Accepted formats are .png, .jpg, .jpeg, and .pdf.</li><li>Documents must be less than 50MB.</li></ul><p class="upload-dialog-note">For this demo, the selected file name will appear in the verification table. It is not uploaded to a server.</p><div class="upload-dialog-actions"><button type="button" class="upload-cancel">Cancel</button><button type="button" class="upload-continue">Continue</button></div></div></div><script>
(() => {
  const modal = document.getElementById('upload-modal');
  if (!modal) return;
  let pendingInput = null;
  let allowPicker = false;
  const close = () => { modal.hidden = true; pendingInput = null; };
  document.querySelectorAll('.upload-button input[type="file"]').forEach((input) => {
    input.addEventListener('click', (event) => { if (allowPicker) { allowPicker = false; return; } event.preventDefault(); pendingInput = input; modal.hidden = false; });
    input.addEventListener('change', () => {
      const file = input.files[0];
      if (!file) return;
      input.closest('.upload-button').classList.add('has-file');
      input.closest('.upload-button').childNodes[0].textContent = '✓ ' + file.name;
    });
  });
  modal.querySelector('.upload-close').addEventListener('click', close);
  modal.querySelector('.upload-cancel').addEventListener('click', close);
  modal.querySelector('.upload-continue').addEventListener('click', () => { modal.hidden = true; if (pendingInput) { allowPicker = true; pendingInput.click(); } });
})();
</script><script>
(() => {
  const files = [...document.querySelectorAll('.verification-main input[type="file"]')];
  const next = document.getElementById('verification-next');
  if (files.length && next) {
    const update = () => { next.disabled = !files.every((input) => input.files.length > 0); };
    files.forEach((input) => input.addEventListener('change', update));
    next.addEventListener('click', () => { if (!next.disabled) window.location.href = 'index.php?page=identity'; });
    update();
  }
  document.querySelectorAll('input[name="verification_method"]').forEach((radio) => radio.addEventListener('change', () => { const button = document.querySelector('.identity-next'); if (button) button.disabled = false; }));
})();
</script></body></html>























